using System.Text.Json;
using Quiberon.Simulation;
using Xunit;
public class AiCommanderTests
{
    static Rules R()=>new(){Width=1400,Height=800,CombatEnabled=true,MoraleEnabled=true,CavalryEnabled=true,ArtilleryEnabled=true,SpecialistsEnabled=true,AiEnabled=true,CommandersEnabled=true};
    static CommanderIdentity C(string p="methodical",string s="drillmaster",int id=0)=>new($"officer-{id}",$"Test Officer {id}","Major","Generic",p,s);
    static Regiment U(int id=0,string type="infantry",int army=0,Vec2? p=null,CommanderIdentity? c=null)=>new(id,army,type,Archetypes.Get(type),p??new(400+army*200,300),army==0?0:Math.PI,commander:c);
    static BattleSimulation B(string p="methodical",string s="drillmaster",string type="infantry"){var b=new BattleSimulation([U(type:type,c:C(p,s)),U(1,army:1)],R());b.Ai.ConfigureArmy(0,"balanced");return b;}
    public static IEnumerable<object[]> Probes=>JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"ai_fixtures/probes.json"))).RootElement.EnumerateArray().Select(r=>new object[]{r.GetProperty("input").GetProperty("name").GetString()!,r.GetRawText()});
    [Theory,MemberData(nameof(Probes))]public void CurrentPythonCommanderRulesAndPreparationMatch(string name,string json)
    {
        using var document=JsonDocument.Parse(json);var root=document.RootElement;var definition=root.GetProperty("input").Deserialize<ScenarioDefinition>(ScenarioJson.Options)!;var b=definition.Create();var u=b.Units[0];object result;
        if(root.TryGetProperty("action",out var action) && action.GetString()=="prepare")
        {u.Cohesion=root.GetProperty("cohesion").GetDouble();bool changed=b.Ai.Preparation(u,b.Units[1]);result=new{result=changed,kind=u.Order.Kind.ToString().ToLowerInvariant(),retreatUntil=u.AiRetreatUntil,reformUntil=u.AiReformUntil};}
        else if(root.TryGetProperty("action",out action) && action.GetString()=="intent") {u.Order=new(OrderKind.Advance,b.Units[1].Position);var destination=b.Combat.Intent(u);result=new{destination,facing=u.Facing};}
        else if(root.TryGetProperty("action",out action) && action.GetString()=="skirmish") {u.Order=new(OrderKind.Skirmish,b.Units[1].Position);var destination=b.Ai.Skirmish(u,b.Units[1]);result=new{destination,retreat=u.SkirmishRetreat,until=u.SkirmishUntil};}
        else if(root.TryGetProperty("action",out action) && action.GetString()=="opportunity") {u.AiTarget=1;u.AiTargetUntil=root.GetProperty("lock").GetDouble();var chosen=b.Ai.SelectOpportunity(u,b.Units.Skip(1).ToArray(),b.Units[1]);result=new{target=chosen.Id,until=u.AiTargetUntil};}
        else if(root.TryGetProperty("action",out action) && action.GetString()=="army") {b.Ai.Plan(u,root.GetProperty("strategy").GetString()!);result=new{kind=u.Order.Kind.ToString().ToLowerInvariant(),destination=u.Order.Destination};}
        else{u.Cohesion=85;var p=CommanderSystem.Policy(u);result=new{formation=CommanderSystem.Formation(u),manoeuvre=CommanderSystem.Manoeuvre(u),recovery=CommanderSystem.Recovery(u),shock=CommanderSystem.Shock(u),advance=CommanderSystem.Advance(u),reload=CommanderSystem.Reload(u),accuracy=CommanderSystem.Accuracy(u,1),defence=CommanderSystem.Defence(u,b.Units[1]),policy=new{commitment=p.Commitment,pursuit_distance=p.PursuitDistance,disengage_seconds=p.DisengageSeconds,overmatch=p.Overmatch,firing_distance=p.FiringDistance},scatter=CommanderSystem.Scatter(u),redeploy=CommanderSystem.Redeploy(u),pursuit=CommanderSystem.Pursuit(u),gap=CommanderSystem.PursuitGap(u,6),frontal=CommanderSystem.FrontalPenalty(u,b.Units[1]),chargeShock=CommanderSystem.ChargeShock(u,b.Units[1],.7,false)};}
        using var actual=JsonDocument.Parse(JsonSerializer.Serialize(result,ScenarioJson.Options));CombatReferenceTests.Compare(root.GetProperty("expected"),actual.RootElement,name);
    }
    [Fact]public void OfficersAreDeterministicUniqueCompatibleAndCombatSeedIndependent(){var d=CombatScenarios.Get("ai-combined");var a=d.Create();var b=(d with{Seed=999}).Create();Assert.Equal(a.Units.Select(u=>u.Commander),b.Units.Select(u=>u.Commander));Assert.Equal(12,a.Units.Select(u=>u.Commander.Id).Distinct().Count());foreach(var u in a.Units)CommanderSystem.Validate(u.Commander,u.Archetype.Category);Assert.Equal(0,a.Random.Draws);var json=JsonSerializer.Serialize(a.Units[0].Commander,ScenarioJson.Options);Assert.Equal(a.Units[0].Commander,JsonSerializer.Deserialize<CommanderIdentity>(json,ScenarioJson.Options));}
    [Fact]public void CuratedNamesAreWholeRankFreeAndRemainUnique(){var names=new HashSet<string>();var ids=new HashSet<string>();var rng=new SimulationRandom(18);var list=Enumerable.Range(0,9).Select(_=>CommanderSystem.Generate(rng,UnitCategory.Infantry,"Haudenosaunee Confederacy",names,ids)).ToArray();Assert.All(list,c=>Assert.Equal("",c.Rank));Assert.Equal(9,list.Select(c=>c.Name).Distinct().Count());Assert.Contains(list,c=>c.Name=="Tyorhansera");Assert.Contains(list,c=>c.Name=="Akiatonharónkwen");}
    sealed class RepeatingRandom:ISimulationRandom{public long Draws{get;private set;}public double NextDouble(){Draws++;return .5;}}
    [Fact]public void GenerationRemainsBoundedWithARepeatingTestRandomStream(){var rng=new RepeatingRandom();var names=new HashSet<string>();var ids=new HashSet<string>();var first=CommanderSystem.Generate(rng,UnitCategory.Infantry,"Generic",names,ids);var next=CommanderSystem.Generate(rng,UnitCategory.Infantry,"Generic",names,ids);Assert.NotEqual(first.Id,next.Id);Assert.NotEqual(first.Name,next.Name);}
    [Fact]public void CompatibleCrossFactionOfficerAndInvalidDataValidation(){CommanderSystem.Validate(new("one","Friedrich Adler","Major","Prussia","methodical","artillerist"),UnitCategory.Artillery);Assert.Throws<ArgumentException>(()=>CommanderSystem.Validate(C(s:"artillerist"),UnitCategory.Infantry));Assert.Throws<ArgumentException>(()=>CommanderSystem.Validate(C(p:"invented"),UnitCategory.Infantry));}
    [Fact]public void PlayerHoldAndMoveSurviveAiUpdatesAndCanReleaseAutonomy(){var b=B("aggressive");b.Issue(new(0,new(OrderKind.Hold)));for(int i=0;i<110;i++)b.Step();Assert.True(b.Units[0].PlayerOrder);Assert.Equal(OrderKind.Hold,b.Units[0].Order.Kind);b.Issue(new(0,new(OrderKind.Move,new(350,180))));for(int i=0;i<60;i++)b.Step();Assert.Equal(OrderKind.Move,b.Units[0].Order.Kind);b.Issue(new(0,Autonomy:AutonomyMode.Autonomous));b.Step();Assert.False(b.Units[0].PlayerOrder);Assert.NotEqual(OrderKind.Move,b.Units[0].Order.Kind);}
    [Fact]public void CautiousCommanderObeysExplicitAttack(){var b=B("cautious");b.Units[0].Strength=50;b.Issue(new(0,new(OrderKind.Attack,TargetId:1)));for(int i=0;i<100;i++)b.Step();Assert.Equal(OrderKind.Attack,b.Units[0].Order.Kind);Assert.Equal(1,b.Units[0].Order.TargetId);Assert.True(b.Units[0].PlayerOrder);}
    [Fact]public void InvalidAttackReleasesAutonomyButHoldRemainsBinding(){var b=B();b.Issue(new(0,new(OrderKind.Attack,TargetId:1)));b.Step();b.Units[1].Strength=0;b.Step();Assert.False(b.Units[0].PlayerOrder);Assert.Null(b.Units[0].TargetId);Assert.Null(b.Units[0].AiTarget);}
    [Fact]public void MethodicalPreparesCautiousRetreatsAndAggressiveCommits(){var method=B("methodical");method.Units[0].Cohesion=40;method.Ai.Plan(method.Units[0],"balanced");Assert.Equal(OrderKind.Hold,method.Units[0].Order.Kind);var cautious=B("cautious");cautious.Units[1].Position=new(460,300);cautious.Units[0].Strength=80;cautious.Ai.Plan(cautious.Units[0],"balanced");Assert.Equal(OrderKind.Move,cautious.Units[0].Order.Kind);var aggro=B("aggressive");aggro.Units[1].Position=new(460,300);aggro.Units[0].Strength=80;aggro.Ai.Plan(aggro.Units[0],"balanced");Assert.Equal(OrderKind.Advance,aggro.Units[0].Order.Kind);}
    [Fact]public void OpportunisticChoiceIsVulnerabilityAwareAndPersistent(){var b=new BattleSimulation([U(c:C("opportunistic")),U(1,army:1,p:new(490,300)),U(2,army:1,p:new(550,300))],R());b.Ai.ConfigureArmy(0,"balanced");b.Units[2].State=MoraleState.Wavering;b.Units[2].Cohesion=25;b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(2,b.Units[0].AiTarget);b.Units[1].Cohesion=1;b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(2,b.Units[0].AiTarget);}
    [Fact]public void OpportunisticCavalryActuallyCommitsToItsNewVulnerableTarget(){var b=new BattleSimulation([U(type:"cavalry",c:C("opportunistic","firebrand")),U(1,army:1,p:new(490,300)),U(2,army:1,p:new(550,300))],R());b.Ai.ConfigureArmy(0,"balanced");b.Units[0].Order=new(OrderKind.Attack,TargetId:1);b.Units[0].CavalryTargetId=1;b.Units[0].AiTarget=1;b.Units[2].State=MoraleState.Wavering;b.Units[2].Cohesion=25;b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(2,b.Units[0].Order.TargetId);Assert.Equal(2,b.Units[0].CavalryTargetId);}
    [Fact]public void HiddenOrderedTargetDoesNotDiscardAVisiblePersistentCavalryTarget(){var b=new BattleSimulation([U(type:"cavalry",c:C("aggressive","firebrand")),U(1,army:1,p:new(700,300)),U(2,army:1,p:new(700,650)),U(3,type:"artillery",army:1,p:new(500,100))],R(),new([new(550,300,15,60,20,true)]));b.Ai.ConfigureArmy(0,"balanced");var u=b.Units[0];u.Order=new(OrderKind.Attack,TargetId:1);u.CavalryTargetId=2;u.AiTarget=2;b.Units[3].State=MoraleState.Routing;b.Units[3].Cohesion=0;Assert.False(b.Perceives(u,b.Units[1]));Assert.True(b.Perceives(u,b.Units[2]));b.Ai.Plan(u,"balanced");Assert.Equal(2,u.AiTarget);Assert.Equal(2,u.CavalryTargetId);}
    [Fact]public void CavalryAvoidsPreparedFrontalRushButChargesBrokenTarget(){var b=B("cautious","firebrand","cavalry");b.Units[1].Position=new(490,300);b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(OrderKind.Move,b.Units[0].Order.Kind);b.Units[1].State=MoraleState.Wavering;b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(OrderKind.Attack,b.Units[0].Order.Kind);for(int i=0;i<50;i++)b.Step();Assert.True(b.Metrics.ChargeStarts>0);Assert.True(b.Metrics.AbortedCharges<=1);}
    [Fact]public void AutonomousPursuitHasPersonalityLimitButExplicitPursuitDoesNot(){var b=B("cautious","pursuit_specialist","cavalry");var u=b.Units[0];var t=b.Units[1];t.State=MoraleState.Routing;u.CavalryState=CavalryState.Pursuit;u.AiPursuitTarget=t.Id;u.AiPursuitOrigin=u.Position-new Vec2(130,0);Assert.True(b.Ai.LimitPursuit(u,t));u.PlayerOrder=true;u.CavalryState=CavalryState.Pursuit;u.AiPursuitOrigin=u.Position-new Vec2(1000,0);Assert.False(b.Ai.LimitPursuit(u,t));}
    [Fact]public void SkirmishRetreatIsBoundedAndRiflesHoldTheirRange(){var b=B("aggressive","sharpshooter","revolutionary_rifles");var u=b.Units[0];b.Units[1].Position=new(440,300);Assert.NotNull(b.Ai.Skirmish(u,b.Units[1]));Assert.True(u.SkirmishRetreat);u.SkirmishUntil=0;b.Units[1].Position=new(575,300);Assert.Null(b.Ai.Skirmish(u,b.Units[1]));Assert.False(u.SkirmishRetreat);}
    [Fact]public void ArtilleryRiskFilterOnlyAppliesToAiAndCannotMakeShotsHarmless(){var b=new BattleSimulation([U(type:"artillery",c:C(s:"artillerist")),U(1,army:0,p:new(420,300)),U(2,army:1,p:new(600,300))],R());b.Ai.ConfigureArmy(0,"balanced");Assert.True(b.Ai.UnsafeShot(b.Units[0],b.Units[2]));Assert.False(b.Combat.CanFire(b.Units[0],b.Units[2]));b.Issue(new(0,new(OrderKind.Attack,TargetId:2)));b.Step();Assert.True(b.Metrics.ArtilleryShots>0);for(int i=0;i<50;i++)b.Step();Assert.True(b.Metrics.FriendlyFireHits>0);}
    [Fact]public void BatteryFindsClearPositionCommitsDeploysAndFires(){var b=new BattleSimulation([U(type:"artillery",p:new(300,300),c:C(s:"artillerist")),U(1,p:new(400,470)),U(2,army:1,p:new(610,300))],R(),new([new(450,300,25,14,18,true)]));b.Units[1].PlayerOrder=true;b.Ai.ConfigureArmy(0,"balanced");b.Ai.Plan(b.Units[0],"balanced");Assert.Equal(OrderKind.Move,b.Units[0].Order.Kind);Assert.Equal(60,b.Units[0].AiPositionUntil);for(int i=0;i<900;i++)b.Step();Assert.True(b.Metrics.ArtilleryShots>0,$"No shots: {b.Units[0].Position} facing {b.Units[0].Facing} {b.Units[0].Order} {b.Units[0].BatteryState} setup {b.Units[0].SetupLeft} intention {b.Units[0].AiIntention}");Assert.True(b.Units[0].MovingSeconds<80,$"Movement {b.Units[0].MovingSeconds}");}
    [Fact]public void SpecializationsModifyExistingMechanicsAndStackWithinBounds(){var b=B(s:"drillmaster",type:"prussian_line");Assert.InRange(SpecialistSystem.FormationTime(b.Units[0],7),3.5,4);var path=B(s:"pathfinder");var terrain=new TerrainMap(forests:[new(400,300,150,150,1)]);var generic=new Regiment(99,0,"Generic",Archetypes.Get("infantry"),new(400,300));Assert.True(terrain.MovementEffect(path.Units[0],new(1,0)).Speed>terrain.MovementEffect(generic,new(1,0)).Speed);var rifles=B(s:"sharpshooter");Assert.Equal(12*1.08,SpecialistSystem.Reload(rifles.Units[0]),8);var guns=B(s:"artillerist",type:"artillery");Assert.Equal(.88,CommanderSystem.Scatter(guns.Units[0]));Assert.Equal(1.1,CommanderSystem.Redeploy(guns.Units[0]));var insp=B(s:"inspirer");Assert.Equal(.12,CommanderSystem.Aura(insp.Units[0]));}
    [Fact]public void AutonomousCavalryPatienceDependsOnPersonality(){double First(string personality){var b=new BattleSimulation([U(type:"cavalry",c:C(personality,"firebrand")),U(1,type:"artillery",army:1,p:new(700,300))],R());b.Units[1].HoldFire=true;b.Ai.ConfigureArmy(0,"balanced");for(int i=0;i<1200 && !b.Events.Any(e=>e.Kind=="charge_start");i++)b.Step();return b.Events.First(e=>e.Kind=="charge_start").Time;}Assert.True(First("aggressive")<First("cautious"));}
    [Fact]public void ExplicitFormationIsPinnedUntilAutonomyIsReleased(){var b=B("aggressive");b.Units[1].Position=new(1000,300);b.Issue(new(0,Formation:Formation.Line));b.Units[0].Formation=Formation.Column;b.Issue(new(0,Formation:Formation.Line));for(int i=0;i<300;i++)b.Step();Assert.Equal(Formation.Line,b.Units[0].Formation);Assert.True(b.Units[0].PlayerFormationPinned);b.Issue(new(0,Autonomy:AutonomyMode.Autonomous));b.Step();Assert.False(b.Units[0].PlayerFormationPinned);}
    [Fact]public void DefensiveAnchorsUseClampedInitialFootprints(){var b=new BattleSimulation([U(p:new(-50,-50))],R());Assert.Equal(b.Units[0].Position,b.Ai.Anchors[0]);}
    [Fact]public void FirebrandHasConditionalImpactAndDisorderAndSupportsInfantry(){Assert.Contains("firebrand",CommanderSystem.Usable(UnitCategory.Infantry));var b=B("aggressive","firebrand","cavalry");var u=b.Units[0];var target=b.Units[1];target.State=MoraleState.Wavering;target.Cohesion=30;u.CavalryState=CavalryState.Charging;u.ChargeMomentum=.7;u.Velocity=new(8,0);u.Speed=8;b.Cavalry.Impact(u,target);Assert.Equal(100-3*.7,u.Cohesion,8);Assert.Equal(24*.7*1.12,b.Metrics.ImpactMoraleShock,8);}
    [Fact]public void CommanderAssignmentIsSetupOnly(){var b=B();Assert.True(b.AssignCommander(0,C("aggressive","firebrand")));b.Step();Assert.False(b.AssignCommander(0,C("cautious","firebrand")));}
    [Fact]public void FullAutonomousCombinedArmsBattleCompletesWithoutIdleRegiments(){var b=CombatScenarios.Get("ai-combined").Create();for(int i=0;i<10000 && b.Result is null;i++)b.Step();Assert.NotNull(b.Result);Assert.True(b.Metrics.ArtilleryShots>0 && b.Metrics.ChargeStarts>0 && b.Metrics.Volleys>0 && b.Metrics.Routs>0);Assert.All(b.Units,u=>Assert.True(u.ShotsFired>0 || u.DamageInflicted>0));}
    [Theory][InlineData(17)][InlineData(31)]public void AutonomousInfantryBattleCompletesAndIsReproducible(int seed){string Run(){var d=CombatScenarios.Get("ai-infantry") with{Seed=seed};var b=d.Create();for(int i=0;i<10000 && b.Result is null;i++)b.Step();Assert.NotNull(b.Result);Assert.True(b.Metrics.Volleys>0 && b.Metrics.Routs>0);return JsonSerializer.Serialize(new{snapshot=b.Snapshot(),draws=b.Random.Draws,events=b.Events},ScenarioJson.Options);}Assert.Equal(Run(),Run());}
}
